 async function context({updateCurrent=true}={}){const token=++contextEpoch,data=await api('/context');if(disposed||token!==contextEpoch)return;topics=arr(data.topics);styles=arr(data.styles);jobs=arr(data.jobs);plans=arr(data.plans);renderOptions();renderHistory();if(updateCurrent&&job&&Array.isArray(data.jobs)){const live=jobs.find(j=>j.jobId===job.jobId);if(!live){jobEpoch++;clearTimeout(poll);job=null;syncResults({results:[]});status();controls();notify('这次研究已不可见，屏幕内容已清除。隐藏或回收站资料不会继续展示。');}else if(!running(job)){job={...live,status:live.status||live.phase};if(Array.isArray(live.results)){const prior=new Map(arr(result?.results).map(row=>[row.recordId,row]));const visibleRows=live.results.map(row=>{const old=prior.get(row.recordId),a=resultOf(row),b=old&&resultOf(old);return b?.evidence&&a.evidenceRef?.analysisId===b.evidenceRef?.analysisId?{...row,result:{...a,evidence:b.evidence}}:row;});syncResults({...result,...live,jobId:live.jobId,results:visibleRows});}status();controls();if(running(job))loadJob(job.jobId).catch(showError);}}}
